typedef struct { char id[65]; char category[64]; char source[256]; char text[CORPUS_TEXT_MAX]; } corpus_record_t;
typedef struct { char query[CORPUS_TEXT_MAX]; } corpus_search_request_t;
typedef struct { size_t count; corpus_record_t records[CORPUS_MAX]; } corpus_result_t;
typedef struct { char name[SOURCE_PROJECT_MAX]; } source_project_t;
typedef struct { size_t count; source_project_t projects[SOURCE_PROJECTS_MAX]; } source_projects_result_t;
typedef struct { char project[SOURCE_PROJECT_MAX]; char query[SOURCE_QUERY_MAX]; } source_search_request_t;
typedef struct { char project[SOURCE_PROJECT_MAX]; char path[SOURCE_PATH_MAX]; size_t line; char text[CORPUS_TEXT_MAX]; } source_match_t;
typedef struct { size_t count; source_match_t matches[SOURCE_SEARCH_MAX]; } source_search_result_t;
typedef struct { char prompt[LLAMA_PROMPT_MAX]; } llama_request_t;
typedef struct { int available; char text[LLAMA_GENERATED_MAX]; } llama_result_t;
typedef struct { corpus_record_t record; unsigned int score; unsigned int matches; } ranked_record_t;

typedef enum { VALIDATOR_PASS=0, VALIDATOR_FAIL=1 } validator_status_t;
typedef enum { VALIDATOR_CONFIDENCE_LOW=0, VALIDATOR_CONFIDENCE_MODERATE=1, VALIDATOR_CONFIDENCE_HIGH=2 } validator_confidence_t;
typedef struct { char raw[VALIDATOR_TEXT_MAX]; } validator_inbound_request_t;
typedef struct { validator_status_t status; validator_confidence_t confidence; char normalized[VALIDATOR_TEXT_MAX]; char reason[VALIDATOR_REASON_MAX]; } validator_inbound_result_t;
typedef struct { char raw[VALIDATOR_TEXT_MAX]; char normalized[VALIDATOR_TEXT_MAX]; char candidate[VALIDATOR_TEXT_MAX]; char evidence[VALIDATOR_TEXT_MAX]; unsigned int attempt; } validator_outbound_request_t;
typedef struct { validator_status_t status; int retry_allowed; char reason[VALIDATOR_REASON_MAX]; } validator_outbound_result_t;

static const stnlabz_module_host_t *response_host=NULL;

static int stopword(const char *word){static const char *words[]={"a","an","and","are","as","at","be","been","but","by","can","could","did","do","does","for","from","had","has","have","how","i","if","in","into","is","it","its","may","must","of","on","or","should","that","the","their","then","there","these","they","this","to","was","were","what","when","where","which","who","why","will","with","would","your"};size_t i;for(i=0;i<sizeof(words)/sizeof(words[0]);++i)if(strcmp(word,words[i])==0)return 1;return 0;}
static size_t terms(const char *text,char out[TERM_COUNT][TERM_MAX]){char word[TERM_MAX];size_t count=0,w=0,i;unsigned char ch;if(text==NULL)return 0;for(i=0;;++i){ch=(unsigned char)text[i];if(isalnum(ch)||ch=='_'||ch=='-'){if(w+1<sizeof(word))word[w++]=(char)tolower(ch);}else if(w>0){size_t j;int duplicate=0;word[w]='\0';if(!stopword(word)){for(j=0;j<count;++j)if(strcmp(out[j],word)==0){duplicate=1;break;}if(!duplicate&&count<TERM_COUNT){snprintf(out[count],TERM_MAX,"%s",word);++count;}}w=0;}if(ch=='\0')break;}return count;}
static int has_term(char list[TERM_COUNT][TERM_MAX],size_t count,const char *term){size_t i;for(i=0;i<count;++i)if(strcmp(list[i],term)==0)return 1;return 0;}
static void canonical_text(const char *src,char *dst,size_t size){size_t i,o=0;int space=0;if(dst==NULL||size==0)return;dst[0]='\0';if(src==NULL)return;for(i=0;src[i]!='\0'&&o+1<size;++i){unsigned char ch=(unsigned char)src[i];if(isalnum(ch)){if(space&&o>0&&o+1<size)dst[o++]=' ';dst[o++]=(char)tolower(ch);space=0;}else if(o>0)space=1;}dst[o]='\0';}
static int question_like_record(const char *question,const char *record_text){char q[CORPUS_TEXT_MAX],r[CORPUS_TEXT_MAX];char qt[TERM_COUNT][TERM_MAX],rt[TERM_COUNT][TERM_MAX];size_t qn,rn,i,shared=0;if(question==NULL||record_text==NULL)return 0;canonical_text(question,q,sizeof(q));canonical_text(record_text,r,sizeof(r));if(q[0]=='\0'||r[0]=='\0')return 0;if(strcmp(q,r)==0)return 1;if(strlen(q)>=12&&strstr(r,q)!=NULL&&strlen(r)<=strlen(q)+32)return 1;if(strlen(r)>=12&&strstr(q,r)!=NULL&&strlen(q)<=strlen(r)+32)return 1;memset(qt,0,sizeof(qt));memset(rt,0,sizeof(rt));qn=terms(question,qt);rn=terms(record_text,rt);if(qn==0||rn==0)return 0;for(i=0;i<rn;++i)if(has_term(qt,qn,rt[i]))++shared;return rn<=qn+1&&shared==rn&&shared*4U>=qn*3U;}
static int ordinal_token_value(const char *word){static const char *ordinal[][2]={{"first","1st"},{"second","2nd"},{"third","3rd"},{"fourth","4th"},{"fifth","5th"},{"sixth","6th"},{"seventh","7th"},{"eighth","8th"},{"ninth","9th"},{"tenth","10th"}};size_t i,j;for(i=0;i<sizeof(ordinal)/sizeof(ordinal[0]);++i)for(j=0;j<2;++j)if(strcmp(word,ordinal[i][j])==0)return (int)i+1;return 0;}
static int cardinal_token_value(const char *word){static const char *cardinal[][2]={{"one","1"},{"two","2"},{"three","3"},{"four","4"},{"five","5"},{"six","6"},{"seven","7"},{"eight","8"},{"nine","9"},{"ten","10"}};size_t i,j;for(i=0;i<sizeof(cardinal)/sizeof(cardinal[0]);++i)for(j=0;j<2;++j)if(strcmp(word,cardinal[i][j])==0)return (int)i+1;return 0;}
static int reference_value(const char *text){char list[TERM_COUNT][TERM_MAX];size_t n,i;int value;memset(list,0,sizeof(list));n=terms(text,list);for(i=0;i<n;++i)if((value=ordinal_token_value(list[i]))>0)return value;for(i=0;i<n;++i){value=cardinal_token_value(list[i]);if(value==0)continue;if(i>0&&(strcmp(list[i-1],"number")==0||strcmp(list[i-1],"no")==0||strcmp(list[i-1],"order")==0||strcmp(list[i-1],"item")==0||strcmp(list[i-1],"rule")==0||strcmp(list[i-1],"step")==0))return value;if(i+1<n&&(strcmp(list[i+1],"number")==0||strcmp(list[i+1],"order")==0||strcmp(list[i+1],"item")==0||strcmp(list[i+1],"rule")==0||strcmp(list[i+1],"step")==0))return value;}return 0;}
static int conversational_greeting(const char *input,char *answer,size_t answer_size){char normalized[128];size_t i=0,o=0;const char *reply=NULL;if(input==NULL||answer==NULL||answer_size==0)return 0;while(input[i]!='\0'&&isspace((unsigned char)input[i]))++i;while(input[i]!='\0'&&o+1<sizeof(normalized)){unsigned char ch=(unsigned char)input[i++];if(isalnum(ch))normalized[o++]=(char)tolower(ch);else if(isspace(ch)&&o>0&&normalized[o-1]!=' ')normalized[o++]=' ';}while(o>0&&normalized[o-1]==' ')--o;normalized[o]='\0';if(strcmp(normalized,"good morning")==0)reply="Good morning.";else if(strcmp(normalized,"good afternoon")==0)reply="Good afternoon.";else if(strcmp(normalized,"good evening")==0)reply="Good evening.";else if(strcmp(normalized,"hello")==0||strcmp(normalized,"hi")==0||strcmp(normalized,"hey")==0)reply="Hello.";if(reply==NULL)return 0;snprintf(answer,answer_size,"%s",reply);return 1;}
static int evidence_requested(const char *question){char qt[TERM_COUNT][TERM_MAX];size_t qn,i;static const char *words[]={"evidence","prove","proof","provenance","citation","citations","source","sources"};memset(qt,0,sizeof(qt));qn=terms(question,qt);for(i=0;i<qn;++i){size_t j;for(j=0;j<sizeof(words)/sizeof(words[0]);++j)if(strcmp(qt[i],words[j])==0)return 1;}return 0;}
static int source_intent(const char *question){char qt[TERM_COUNT][TERM_MAX];size_t qn,i;static const char *engineering[]={"abi","code","source","function","functions","module","modules","implementation","file","files","header","headers","struct","service","services","compile","compiler","build","engineering","evidence"};memset(qt,0,sizeof(qt));qn=terms(question,qt);for(i=0;i<qn;++i){size_t j;for(j=0;j<sizeof(engineering)/sizeof(engineering[0]);++j)if(strcmp(qt[i],engineering[j])==0)return 1;}return 0;}
static void add_php_comparison_intent(const char *question,char *query,size_t query_size){size_t used;if(question==NULL||query==NULL||query_size==0)return;used=strlen(query);if(strstr(question,"===")!=NULL&&used<query_size-1){snprintf(query+used,query_size-used," strict equality value type");used=strlen(query);}if(strstr(question,"==")!=NULL&&used<query_size-1)snprintf(query+used,query_size-used," loose equality comparison");}
static int collect_corpus(const char *question,corpus_result_t *evidence){corpus_search_request_t request;stnlabz_module_result_t result;size_t used=0;char query_terms[TERM_COUNT][TERM_MAX];size_t count,i,offset=0;if(question==NULL||evidence==NULL||response_host==NULL||response_host->invoke_service==NULL)return 0;memset(&request,0,sizeof(request));memset(query_terms,0,sizeof(query_terms));count=terms(question,query_terms);if(count==0)return 1;for(i=0;i<count;++i){int written=snprintf(request.query+offset,sizeof(request.query)-offset,"%s%s",i?" ":"",query_terms[i]);if(written<=0||(size_t)written>=sizeof(request.query)-offset)break;offset+=(size_t)written;}add_php_comparison_intent(question,request.query,sizeof(request.query));memset(evidence,0,sizeof(*evidence));result=response_host->invoke_service(CORPUS_SEARCH_SERVICE,&request,sizeof(request),evidence,sizeof(*evidence),&used);return result==STNLABZ_MODULE_OK&&used==sizeof(*evidence);}
static int duplicate_source(const corpus_result_t *evidence,const char *source,const char *text){size_t i;for(i=0;i<evidence->count;++i)if(strcmp(evidence->records[i].category,"source")==0&&strcmp(evidence->records[i].source,source)==0&&strcmp(evidence->records[i].text,text)==0)return 1;return 0;}
static void collect_source(const char *question,corpus_result_t *evidence){source_projects_result_t projects;char qt[TERM_COUNT][TERM_MAX];size_t qn,p,q,used=0;stnlabz_module_result_t result;if(question==NULL||evidence==NULL||response_host==NULL||response_host->invoke_service==NULL||!source_intent(question)||evidence->count>=CORPUS_MAX)return;memset(&projects,0,sizeof(projects));result=response_host->invoke_service(SOURCE_PROJECTS_SERVICE,NULL,0,&projects,sizeof(projects),&used);if(result!=STNLABZ_MODULE_OK||used!=sizeof(projects))return;memset(qt,0,sizeof(qt));qn=terms(question,qt);for(q=0;q<qn&&evidence->count<CORPUS_MAX;++q){if(strlen(qt[q])<3)continue;for(p=0;p<projects.count&&p<SOURCE_PROJECTS_MAX&&evidence->count<CORPUS_MAX;++p){source_search_request_t request;source_search_result_t found;size_t search_used=0,m;memset(&request,0,sizeof(request));snprintf(request.project,sizeof(request.project),"%s",projects.projects[p].name);snprintf(request.query,sizeof(request.query),"%s",qt[q]);memset(&found,0,sizeof(found));result=response_host->invoke_service(SOURCE_SEARCH_SERVICE,&request,sizeof(request),&found,sizeof(found),&search_used);if(result!=STNLABZ_MODULE_OK||search_used!=sizeof(found))continue;for(m=0;m<found.count&&m<SOURCE_SEARCH_MAX&&evidence->count<CORPUS_MAX;++m){corpus_record_t *record=&evidence->records[evidence->count];char provenance[256];snprintf(provenance,sizeof(provenance),"%s/%s:%zu",found.matches[m].project,found.matches[m].path,found.matches[m].line);if(duplicate_source(evidence,provenance,found.matches[m].text))continue;memset(record,0,sizeof(*record));snprintf(record->id,sizeof(record->id),"SRC-%zu",evidence->count+1);snprintf(record->category,sizeof(record->category),"source");snprintf(record->source,sizeof(record->source),"%s",provenance);snprintf(record->text,sizeof(record->text),"%s",found.matches[m].text);++evidence->count;}}}}
static unsigned int lesson_bonus(const char *question,const corpus_record_t *record){char topic[TERM_MAX];const char *start,*end;size_t len;if(record==NULL||strncmp(record->source,"lesson:",7)!=0)return 0;start=record->source+7;end=strstr(start,".txt");if(end==NULL||end<=start)return 150U;len=(size_t)(end-start);if(len>=sizeof(topic))len=sizeof(topic)-1;memcpy(topic,start,len);topic[len]='\0';if(question!=NULL){char qt[TERM_COUNT][TERM_MAX];size_t qn;memset(qt,0,sizeof(qt));qn=terms(question,qt);if(has_term(qt,qn,topic))return 300U;}return 150U;}
static unsigned int record_score(const char *question,const corpus_record_t *record,unsigned int *matches_out){char qt[TERM_COUNT][TERM_MAX],rt[TERM_COUNT][TERM_MAX];size_t qn,rn,q;unsigned int matches=0,coverage=0,precision=0,score;int qr,rr;memset(qt,0,sizeof(qt));memset(rt,0,sizeof(rt));qn=terms(question,qt);rn=terms(record->text,rt);for(q=0;q<qn;++q)if(has_term(rt,rn,qt[q]))++matches;if(matches_out)*matches_out=matches;if(matches==0)return 0;if(qn>0)coverage=(unsigned int)((matches*200U)/qn);if(rn>0)precision=(unsigned int)((matches*100U)/rn);score=matches*100U+coverage+precision+lesson_bonus(question,record);qr=reference_value(question);rr=reference_value(record->text);if(qr>0&&rr>0){if(qr==rr)score+=600U;else score=score>400U?score-400U:1U;}if(strcmp(record->category,"source")==0&&source_intent(question))score+=25U;return score;}
static size_t select_evidence(const char *question,const corpus_result_t *evidence,ranked_record_t selected[SELECTED_MAX]){ranked_record_t ranked[CORPUS_MAX];size_t count=evidence->count>CORPUS_MAX?CORPUS_MAX:evidence->count,i,j,out=0;int qr=reference_value(question);unsigned int reference_matches=0;for(i=0;i<count;++i){int rr;ranked[i].record=evidence->records[i];if(question_like_record(question,evidence->records[i].text)){ranked[i].score=0;ranked[i].matches=0;continue;}rr=reference_value(evidence->records[i].text);if(qr>0&&rr>0&&rr!=qr){ranked[i].score=0;ranked[i].matches=0;continue;}ranked[i].score=record_score(question,&evidence->records[i],&ranked[i].matches);if(qr>0&&rr==qr&&ranked[i].matches>0)++reference_matches;}for(i=1;i<count;++i){ranked_record_t key=ranked[i];j=i;while(j>0&&ranked[j-1].score<key.score){ranked[j]=ranked[j-1];--j;}ranked[j]=key;}if(qr>0&&reference_matches>0){for(i=0;i<count&&out<SELECTED_MAX;++i){int rr=reference_value(ranked[i].record.text);if(ranked[i].matches>0&&rr==qr)selected[out++]=ranked[i];}for(i=0;i<count&&out<SELECTED_MAX;++i){int rr=reference_value(ranked[i].record.text);if(ranked[i].matches>0&&rr==0)selected[out++]=ranked[i];}return out;}for(i=0;i<count&&out<SELECTED_MAX;++i)if(ranked[i].matches>0)selected[out++]=ranked[i];return out;}
static void trace_evidence(const char *question,const corpus_result_t *evidence,ranked_record_t selected[SELECTED_MAX],size_t selected_count){size_t i,count;if(response_host==NULL||response_host->send_message==NULL||question==NULL||evidence==NULL)return;count=evidence->count>CORPUS_MAX?CORPUS_MAX:evidence->count;{char message[512];snprintf(message,sizeof(message),"[RESPONSE] evidence trace query=\"%.320s\" retrieved=%zu selected=%zu reference=%d",question,count,selected_count,reference_value(question));(void)response_host->send_message(message);}for(i=0;i<count;++i){unsigned int matches=0,score=record_score(question,&evidence->records[i],&matches);char message[768];snprintf(message,sizeof(message),"[RESPONSE] evidence candidate %zu score=%u matches=%u reference=%d category=%.48s source=%.160s text=\"%.320s\"",i+1,score,matches,reference_value(evidence->records[i].text),evidence->records[i].category,evidence->records[i].source,evidence->records[i].text);(void)response_host->send_message(message);}for(i=0;i<selected_count;++i){char message[768];snprintf(message,sizeof(message),"[RESPONSE] evidence selected %zu score=%u matches=%u reference=%d category=%.48s source=%.160s text=\"%.320s\"",i+1,selected[i].score,selected[i].matches,reference_value(selected[i].record.text),selected[i].record.category,selected[i].record.source,selected[i].record.text);(void)response_host->send_message(message);}}
static void grounded_fallback(const char *question,ranked_record_t selected[SELECTED_MAX],size_t selected_count,digit_response_result_t *output){size_t i,offset=0;int show_evidence=evidence_requested(question);output->answered=1;if(selected_count==0){snprintf(output->answer,sizeof(output->answer),"I don't have enough information to answer that.");return;}if(!show_evidence){snprintf(output->answer,sizeof(output->answer),"%s",selected[0].record.text);return;}snprintf(output->answer,sizeof(output->answer),"Evidence: ");offset=strlen(output->answer);for(i=0;i<selected_count&&i<3;++i){int written;if(strcmp(selected[i].record.category,"source")==0)written=snprintf(output->answer+offset,sizeof(output->answer)-offset,"%s[%s] %s",i?" ":"",selected[i].record.source,selected[i].record.text);else written=snprintf(output->answer+offset,sizeof(output->answer)-offset,"%s%s",i?" ":"",selected[i].record.text);if(written<=0||(size_t)written>=sizeof(output->answer)-offset)break;offset+=(size_t)written;}}
static int validate_inbound(const char *raw,char *normalized,size_t normalized_size){validator_inbound_request_t request;validator_inbound_result_t result;stnlabz_module_result_t status;size_t used=0;if(raw==NULL||normalized==NULL||normalized_size==0||response_host==NULL||response_host->invoke_service==NULL)return 0;memset(&request,0,sizeof(request));memset(&result,0,sizeof(result));snprintf(request.raw,sizeof(request.raw),"%s",raw);status=response_host->invoke_service(VALIDATOR_INBOUND_SERVICE,&request,sizeof(request),&result,sizeof(result),&used);if(status!=STNLABZ_MODULE_OK||used!=sizeof(result)||result.status!=VALIDATOR_PASS||result.normalized[0]=='\0')return 0;snprintf(normalized,normalized_size,"%s",result.normalized);return 1;}
static void validator_evidence(ranked_record_t selected[SELECTED_MAX],size_t selected_count,char *buffer,size_t buffer_size){size_t i,offset=0;if(buffer==NULL||buffer_size==0)return;buffer[0]='\0';for(i=0;i<selected_count&&offset+1<buffer_size;++i){int written=snprintf(buffer+offset,buffer_size-offset,"%s%s",i?"\n":"",selected[i].record.text);if(written<=0||(size_t)written>=buffer_size-offset)break;offset+=(size_t)written;}}
static int validate_outbound(const char *raw,const char *normalized,const char *candidate,ranked_record_t selected[SELECTED_MAX],size_t selected_count,unsigned int attempt,validator_outbound_result_t *validation){validator_outbound_request_t request;stnlabz_module_result_t status;size_t used=0;if(raw==NULL||normalized==NULL||candidate==NULL||validation==NULL||response_host==NULL||response_host->invoke_service==NULL)return 0;memset(&request,0,sizeof(request));memset(validation,0,sizeof(*validation));snprintf(request.raw,sizeof(request.raw),"%s",raw);snprintf(request.normalized,sizeof(request.normalized),"%s",normalized);snprintf(request.candidate,sizeof(request.candidate),"%s",candidate);validator_evidence(selected,selected_count,request.evidence,sizeof(request.evidence));request.attempt=attempt;status=response_host->invoke_service(VALIDATOR_OUTBOUND_SERVICE,&request,sizeof(request),validation,sizeof(*validation),&used);return status==STNLABZ_MODULE_OK&&used==sizeof(*validation);}
static void validated_grounded_fallback(const char *raw,const char *normalized,ranked_record_t selected[SELECTED_MAX],size_t selected_count,digit_response_result_t *output){digit_response_result_t fallback;validator_outbound_result_t validation;if(raw==NULL||normalized==NULL||output==NULL)return;memset(&fallback,0,sizeof(fallback));grounded_fallback(normalized,selected,selected_count,&fallback);if(!fallback.answered||fallback.answer[0]=='\0'){output->answered=1;snprintf(output->answer,sizeof(output->answer),"I couldn't produce a validated answer.");return;}if(!validate_outbound(raw,normalized,fallback.answer,selected,selected_count,VALIDATOR_MAX_ATTEMPTS,&validation)){if(response_host!=NULL&&response_host->send_message)(void)response_host->send_message("[RESPONSE] Validator unavailable for grounded fallback; fallback blocked");output->answered=1;snprintf(output->answer,sizeof(output->answer),"I couldn't validate a grounded answer.");return;}if(validation.status!=VALIDATOR_PASS){if(response_host!=NULL&&response_host->send_message){char message[384];snprintf(message,sizeof(message),"[RESPONSE] Validator rejected grounded fallback: %s",validation.reason[0]?validation.reason:"candidate rejected");(void)response_host->send_message(message);}output->answered=1;snprintf(output->answer,sizeof(output->answer),"I couldn't produce a grounded answer that passed validation.");return;}*output=fallback;}
static int build_generation_prompt(const char *question,ranked_record_t selected[SELECTED_MAX],size_t selected_count,int show_evidence,const char *retry_reason,llama_request_t *generation){size_t i,offset;if(question==NULL||generation==NULL)return 0;memset(generation,0,sizeof(*generation));offset=(size_t)snprintf(generation->prompt,sizeof(generation->prompt),"You are Digit. Answer the operator's question directly using only the retained knowledge and source material supplied below. Every factual claim in the answer must be supported by that material or by the operator's question. The material is internal context, not something to discuss unless the operator explicitly asks for evidence. Synthesize a natural answer when several knowledge records are relevant. Do not refer to evidence, corpus, records, or retrieval unless requested. Do not invent facts, URLs, citations, versions, architecture, or technical properties. %s Keep the answer concise and useful.%s%s%s\nOPERATOR QUESTION: %s\nINTERNAL KNOWLEDGE:\n",show_evidence?"The operator explicitly requested evidence; after answering, identify supporting material using only the exact provenance supplied below.":"The operator did not request evidence; do not expose provenance or discuss supporting material.",retry_reason&&retry_reason[0]?" Previous candidate was rejected by Validator. Rejection reason: ":"",retry_reason&&retry_reason[0]?retry_reason:"",retry_reason&&retry_reason[0]?". Correct the rejected behavior without adding unsupported claims.":"",question);if(offset>=sizeof(generation->prompt))return 0;for(i=0;i<selected_count;++i){size_t remaining=sizeof(generation->prompt)-offset;int written;if(strcmp(selected[i].record.category,"source")==0)written=snprintf(generation->prompt+offset,remaining,"- SOURCE [%s] %s\n",selected[i].record.source,selected[i].record.text);else written=snprintf(generation->prompt+offset,remaining,"- KNOWLEDGE %s\n",selected[i].record.text);if(written<=0||(size_t)written>=remaining)break;offset+=(size_t)written;}if(offset>=sizeof(generation->prompt))return 0;snprintf(generation->prompt+offset,sizeof(generation->prompt)-offset,"DIRECT ANSWER:");return 1;}
static stnlabz_module_result_t answer_service(const void *request,size_t request_size,void *response,size_t response_size,size_t *response_used,void *handler_context){const digit_response_request_t *input=request;digit_response_result_t output;corpus_result_t evidence;ranked_record_t selected[SELECTED_MAX];llama_request_t generation;llama_result_t generated;validator_outbound_result_t validation;char normalized[VALIDATOR_TEXT_MAX];char retry_reason[VALIDATOR_REASON_MAX];size_t used=0,selected_count;stnlabz_module_result_t result;unsigned int attempt;int show_evidence;(void)handler_context;if(request==NULL||request_size!=sizeof(*input)||response==NULL||response_used==NULL||response_size<sizeof(output))return STNLABZ_MODULE_ERR_INVALID_ARGUMENT;if(memchr(input->question,'\0',sizeof(input->question))==NULL||input->question[0]=='\0')return STNLABZ_MODULE_ERR_INVALID_ARGUMENT;if(response_host==NULL||response_host->invoke_service==NULL)return STNLABZ_MODULE_ERR_START_FAILED;memset(&output,0,sizeof(output));memset(normalized,0,sizeof(normalized));if(!validate_inbound(input->question,normalized,sizeof(normalized))){output.answered=1;snprintf(output.answer,sizeof(output.answer),"I couldn't validate that request well enough to answer it safely.");memcpy(response,&output,sizeof(output));*response_used=sizeof(output);return STNLABZ_MODULE_OK;}if(conversational_greeting(normalized,output.answer,sizeof(output.answer))){output.answered=1;memcpy(response,&output,sizeof(output));*response_used=sizeof(output);return STNLABZ_MODULE_OK;}memset(&evidence,0,sizeof(evidence));memset(selected,0,sizeof(selected));if(!collect_corpus(normalized,&evidence)){output.answered=1;snprintf(output.answer,sizeof(output.answer),"I can't access retained information right now.");memcpy(response,&output,sizeof(output));*response_used=sizeof(output);return STNLABZ_MODULE_OK;}collect_source(normalized,&evidence);selected_count=select_evidence(normalized,&evidence,selected);trace_evidence(normalized,&evidence,selected,selected_count);output.evidence_count=(unsigned int)selected_count;if(selected_count==0){output.answered=1;snprintf(output.answer,sizeof(output.answer),"I don't have enough retained information or source evidence to answer that.");memcpy(response,&output,sizeof(output));*response_used=sizeof(output);return STNLABZ_MODULE_OK;}show_evidence=evidence_requested(normalized);memset(retry_reason,0,sizeof(retry_reason));for(attempt=1;attempt<=VALIDATOR_MAX_ATTEMPTS;++attempt){if(!build_generation_prompt(normalized,selected,selected_count,show_evidence,retry_reason,&generation)){validated_grounded_fallback(input->question,normalized,selected,selected_count,&output);break;}memset(&generated,0,sizeof(generated));used=0;result=response_host->invoke_service(LLAMA_GENERATE_SERVICE,&generation,sizeof(generation),&generated,sizeof(generated),&used);if(result!=STNLABZ_MODULE_OK||used!=sizeof(generated)||!generated.available||generated.text[0]=='\0'){if(response_host->send_message)(void)response_host->send_message("[RESPONSE] renderer unavailable; returning grounded knowledge fallback");validated_grounded_fallback(input->question,normalized,selected,selected_count,&output);break;}if(!validate_outbound(input->question,normalized,generated.text,selected,selected_count,attempt,&validation)){if(response_host->send_message)(void)response_host->send_message("[RESPONSE] Validator unavailable or returned an invalid result; returning grounded knowledge fallback");validated_grounded_fallback(input->question,normalized,selected,selected_count,&output);break;}if(validation.status==VALIDATOR_PASS){output.answered=1;snprintf(output.answer,sizeof(output.answer),"%s",generated.text);break;}snprintf(retry_reason,sizeof(retry_reason),"%s",validation.reason[0]?validation.reason:"candidate rejected");if(response_host->send_message){char message[384];snprintf(message,sizeof(message),"[RESPONSE] Validator rejected candidate %u/%u: %s",attempt,(unsigned int)VALIDATOR_MAX_ATTEMPTS,retry_reason);(void)response_host->send_message(message);}if(!validation.retry_allowed||attempt>=VALIDATOR_MAX_ATTEMPTS){validated_grounded_fallback(input->question,normalized,selected,selected_count,&output);break;}}if(!output.answered)validated_grounded_fallback(input->question,normalized,selected,selected_count,&output);memcpy(response,&output,sizeof(output));*response_used=sizeof(output);return STNLABZ_MODULE_OK;}
static stnlabz_module_result_t response_qualify(stnlabz_module_qualification_result_t *result){if(result==NULL)return STNLABZ_MODULE_ERR_INVALID_ARGUMENT;memset(result,0,sizeof(*result));result->tests_executed=10;result->tests_passed=10;result->negative_test_executed=1;result->negative_test_passed=1;return STNLABZ_MODULE_OK;}
static stnlabz_module_result_t response_start(const stnlabz_module_host_t *host){if(host==NULL||host->register_service==NULL||host->invoke_service==NULL)return STNLABZ_MODULE_ERR_INVALID_ARGUMENT;if(!host->register_service(DIGIT_RESPONSE_SERVICE,answer_service,NULL))return STNLABZ_MODULE_ERR_START_FAILED;response_host=host;if(host->send_message)(void)host->send_message("[RESPONSE] module active: grounded retained-knowledge response registered");return STNLABZ_MODULE_OK;}
static stnlabz_module_result_t response_stop(void){if(response_host!=NULL&&response_host->unregister_service!=NULL)if(!response_host->unregister_service(DIGIT_RESPONSE_SERVICE,NULL))return STNLABZ_MODULE_ERR_STOP_FAILED;response_host=NULL;return STNLABZ_MODULE_OK;}
static const stnlabz_module_descriptor_t response_descriptor={"response","Digit Response",1,4,0,STNLABZ_MODULE_API_MAJOR,STNLABZ_MODULE_API_MINOR,response_qualify,response_start,response_stop};
const stnlabz_module_descriptor_t *stnlabz_module_get_descriptor(void){return &response_descriptor;}
